const raw = 'https://api.example.com:8443/v1/users?page=2&size=10#bio';
const u = new URL(raw);
console.log('原始 URL : ' + raw);
console.log('protocol : ' + u.protocol);
console.log('host     : ' + u.host);
console.log('hostname : ' + u.hostname);
console.log('port     : ' + u.port);
console.log('pathname : ' + u.pathname);
console.log('search   : ' + u.search);
console.log('hash     : ' + u.hash);
console.log('origin   : ' + u.origin);
console.log('query 项 : ' + [...u.searchParams].map(([k, v]) => k + '=' + v).join(', '));
